import React, { useCallback } from "react";
import { Button, ButtonProps } from "@arco-design/web-react";
import { useFormStep } from "../hooks";
import { observer, useForm } from "@formily/react";

const SubmitButton = observer(
  (props: ButtonProps & { onSubmit?: (values) => void | Promise<any> }) => {
    const formStep = useFormStep();
    const form = useForm();

    const onClick = useCallback((e) => {
      props?.onClick?.(e);
      formStep.submit(props.onSubmit);
    }, []);

    return (
      <Button
        type="primary"
        disabled={formStep?.allowNext || form?.submitting}
        loading={form?.submitting}
        {...props}
        onClick={onClick}
      >
        {props.children || "提交"}
      </Button>
    );
  }
);

export default Object.assign(SubmitButton, { __BYTE_BUTTON: true });
